import { createHash } from "node:crypto"
import { deflateSync } from "node:zlib"

function chunk(type: string, data: Buffer): Buffer {
  const body = Buffer.concat([Buffer.from(type), data])
  let crc = 0xffffffff
  for (const byte of body) {
    crc ^= byte
    for (let bit = 0; bit < 8; bit++) crc = (crc >>> 1) ^ ((crc & 1) ? 0xedb88320 : 0)
  }
  const length = Buffer.alloc(4)
  length.writeUInt32BE(data.length)
  const checksum = Buffer.alloc(4)
  checksum.writeUInt32BE((crc ^ 0xffffffff) >>> 0)
  return Buffer.concat([length, body, checksum])
}

/** A complete one-pixel RGB PNG, with deterministic pixels and valid chunk CRCs. */
export function pngBytes(label = "fixture", paddingBytes = 0): Buffer {
  const header = Buffer.alloc(13)
  header.writeUInt32BE(1, 0)
  header.writeUInt32BE(1, 4)
  header[8] = 8
  header[9] = 2
  const pixels = Buffer.concat([Buffer.from([0]), createHash("sha256").update(label).digest().subarray(0, 3)])
  return Buffer.concat([
    Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]),
    chunk("IHDR", header),
    chunk("IDAT", deflateSync(pixels)),
    ...(paddingBytes > 0 ? [chunk("npAD", Buffer.alloc(paddingBytes))] : []),
    chunk("IEND", Buffer.alloc(0)),
  ])
}

// Complete one-pixel fixtures encoded from generated RGB pixels, not image headers.
export const minimalImages = {
  "image/png": pngBytes(),
  "image/gif": Buffer.from("R0lGODdhAQABAIEAAP8AAAAAAAAAAAAAACwAAAAAAQABAAAIBAABBAQAOw==", "base64"),
  "image/jpeg": Buffer.from("", "base64"),
  "image/webp": Buffer.from("UklGRjwAAABXRUJQVlA4IDAAAADQAQCdASoBAAEAAUAmJaACdLoB+AADsAD+8ut//NgVzXPv9//S4P0uD9Lg/9KQAAA=", "base64"),
} as const
